import { buttonBaseClasses } from '@mui/material/ButtonBase';
import { iconButtonClasses } from '@mui/material/IconButton';
import type { Theme } from '@mui/material/styles';
import type { SystemStyleObject } from '@mui/system';
import { svTokens } from '../../theme/tokens';
import {
  buttonColors,
  buttonFocus,
  buttonReducedMotion,
  buttonSize,
} from '../shared/button-shared';
import type {
  SvIconButtonAppearance,
  SvIconButtonProps,
} from './sv-icon-button';

type IconButtonState = Pick<SvIconButtonProps, 'color' | 'size' | 'loading'> & {
  appearance: SvIconButtonAppearance;
};

export function iconButtonStyles(
  theme: Theme,
  state: IconButtonState
): SystemStyleObject<Theme> {
  const { appearance, color = 'default', size, loading } = state;
  const palette = (theme.vars ?? theme).palette;
  const tokens = svTokens(theme);
  const colors = buttonColors(theme, color);
  const webinar = appearance === 'webinar';
  const neutralWebinar = webinar && color === 'default';
  const diameter = `${buttonSize(size)}px`;
  const iconSize = webinar ? '20px' : '16px';
  const foreground = neutralWebinar
    ? '#fff'
    : color === 'default'
      ? palette.text.secondary
      : webinar
        ? colors.contrast
        : colors.main;
  const background = neutralWebinar
    ? 'rgba(0,0,0,0.5)'
    : webinar
      ? color === 'inherit'
        ? palette.action.hover
        : colors.main
      : 'transparent';
  const hoverBackground = neutralWebinar
    ? 'rgba(0,0,0,0.6)'
    : webinar
      ? color === 'inherit'
        ? palette.action.selected
        : colors.hover
      : `var(--SvButton-surfaceHover, ${tokens.surfaceHover})`;
  return {
    width: diameter,
    height: diameter,
    padding: '6px',
    boxSizing: 'border-box',
    borderRadius: '999px',
    border: neutralWebinar ? '1px solid currentColor' : 0,
    overflow: 'hidden',
    flexShrink: 0,
    color: foreground,
    background,
    '&:hover': { background: hoverBackground, color: foreground },
    [`&.${buttonBaseClasses.focusVisible}`]: buttonFocus(theme),
    [`&.${iconButtonClasses.disabled}`]: {
      background,
      color:
        neutralWebinar && !loading
          ? 'var(--SvButton-muted, #828282)'
          : foreground,
      opacity: loading || neutralWebinar ? 1 : 0.5,
    },
    // Keep a concrete/inherited foreground for the spinner; hide even fixed-color SVGs and images.
    [`&.${iconButtonClasses.loading}`]: { color: foreground },
    [`& .${iconButtonClasses.loadingIndicator}`]: { color: 'inherit' },
    '& .SvIconButton-icon': {
      display: 'inline-flex',
      alignItems: 'center',
      justifyContent: 'center',
      visibility: loading ? 'hidden' : 'visible',
      '& > svg': { fontSize: iconSize, width: iconSize, height: iconSize },
    },
    '@media (prefers-reduced-motion: reduce)': buttonReducedMotion,
  };
}
